  let n01 = gaussAt(i + vec2f(0.0, 1.0), seed);
  let n11 = gaussAt(i + vec2f(1.0, 1.0), seed);
  return mix(mix(n00, n10, u.x), mix(n01, n11, u.x), u.y);
