fn loadClamped(coords: vec2<i32>) -> vec4<f32> {
  let dims = textureDimensions(source);
  let c = vec2<i32>(
    clamp(coords.x, 0, i32(dims.x) - 1),
    clamp(coords.y, 0, i32(dims.y) - 1)
