  // select transparent black where the offset pushes UV outside the source.
  let oob = s.x < 0.0 || s.x > 1.0 || s.y < 0.0 || s.y > 1.0;
  let col = textureSample(source, samp, s);
  return select(col, vec4f(0.0), oob);
}

